import io.github.diodeme.ji.session.model.*;
import io.github.diodeme.ji.session.model.CanonicalSessionState.*;
import java.time.*;
import java.util.*;

var s1 = new SessionId("session-1");
var s2 = new SessionId("session-2");
var r1 = new RunId("run-1");
var t1 = new TurnId("turn-1");
var modelDone = new Attempt(new AttemptId("model-attempt-1"), t1.value(), 1, AttemptStep.ASSISTANT, AttemptStatus.TERMINAL, Optional.of(AttemptOutcome.SUCCEEDED), 1, "entry-assistant-1");
var toolId = new ToolExecutionId("tool-1");
var toolAttempt = new Attempt(new AttemptId("tool-attempt-1"), toolId.value(), 1, AttemptStep.TOOL, AttemptStatus.RUNNING, Optional.empty(), 0, "entry-tool-1");
var foreignTool = new ToolExecution(toolId, s2, r1, t1, "call-1", "read", "entry-tool-1", List.of(toolAttempt), ToolRetryContract.READ_ONLY, Optional.empty(), ToolStatus.RUNNING, Optional.empty(), 0);
var foreignTurn = new Turn(t1, r1, 1, TurnStatus.WAITING_FOR_TOOLS, Optional.empty(), Optional.empty(), 0, List.of(modelDone), List.of(foreignTool), List.of());
var foreignRun = new Run(r1, s1, RunStatus.RUNNING, Optional.empty(), Optional.empty(), 0, List.of(foreignTurn), Instant.EPOCH, Optional.empty());
try { new CanonicalSessionState(s1, SessionStatus.AVAILABLE, 1, Optional.of(foreignRun), List.of(), List.of()); System.out.println("COUNTEREXAMPLE_FOREIGN_TOOL_SESSION=ACCEPTED"); } catch (Exception e) { System.out.println("COUNTEREXAMPLE_FOREIGN_TOOL_SESSION=REJECTED:" + e.getClass().getSimpleName()); }

var activeAttempt = new Attempt(new AttemptId("model-attempt-2"), t1.value(), 1, AttemptStep.ASSISTANT, AttemptStatus.RUNNING, Optional.empty(), 0, "entry-assistant-2");
var inconsistentPausedTurn = new Turn(t1, r1, 1, TurnStatus.PAUSED, Optional.empty(), Optional.of(TurnPhase.MODEL_STREAMING), 0, List.of(activeAttempt), List.of(), List.of());
var inconsistentPausedRun = new Run(r1, s1, RunStatus.PAUSED, Optional.empty(), Optional.of(RunPauseReason.HOST_RESTART), 0, List.of(inconsistentPausedTurn), Instant.EPOCH, Optional.empty());
try { new CanonicalSessionState(s1, SessionStatus.AVAILABLE, 1, Optional.of(inconsistentPausedRun), List.of(), List.of()); System.out.println("COUNTEREXAMPLE_PAUSED_CHILD_RUNNING=ACCEPTED"); } catch (Exception e) { System.out.println("COUNTEREXAMPLE_PAUSED_CHILD_RUNNING=REJECTED:" + e.getClass().getSimpleName()); }

var c1 = new CompactionId("compaction-1");
var ca = new Attempt(new AttemptId("compaction-attempt-1"), c1.value(), 1, AttemptStep.COMPACTION, AttemptStatus.RUNNING, Optional.empty(), 0, "entry-summary-1");
var runningCompaction = new Compaction(c1, s1, CompactionStatus.RUNNING, Optional.empty(), 0, List.of(ca), Optional.empty());
var compactionOnlyState = new CanonicalSessionState(s1, SessionStatus.AVAILABLE, 1, Optional.empty(), List.of(), List.of(runningCompaction));
var afterRestart = Recovery.pauseAfterRestart(compactionOnlyState);
System.out.println("COUNTEREXAMPLE_COMPACTION_WITHOUT_RUN=" + afterRestart.compactions().getFirst().status() + ",SAME_OBJECT=" + (afterRestart == compactionOnlyState));

System.out.println("SESSION_COMPONENTS=" + Arrays.stream(CanonicalSessionState.class.getRecordComponents()).map(c -> c.getName()).toList());

var commandWatermark = new CanonicalFacts.CommandWatermark(s1, 0);
var deliveryBefore = new CanonicalFacts.DeliveryWatermark(s1, 1, 0, 0, 0);
var deliveryAfterSnapshot = deliveryBefore.installSnapshot(1, 1);
try { new CanonicalFacts.HostCommit(Optional.empty(), commandWatermark, commandWatermark, new CanonicalFacts.FollowUpQueue(0, List.of()), new CanonicalFacts.AgentSessionLog(List.of(), 1), List.of(), deliveryBefore, deliveryAfterSnapshot, 1); System.out.println("SNAPSHOT_ONLY_HOST_COMMIT=ACCEPTED"); } catch (Exception e) { System.out.println("SNAPSHOT_ONLY_HOST_COMMIT=REJECTED:" + e.getMessage()); }

System.out.println("FOLLOW_UP_QUEUE_METHODS=" + Arrays.stream(CanonicalFacts.FollowUpQueue.class.getDeclaredMethods()).map(m -> m.getName()).sorted().toList());
/exit
'@ | jshell --class-path "ji-java\core\ji-session-api\build\classes\java\main"

$manifest = Get-Content -Raw 'contracts/fixtures/manifest.json' | ConvertFrom-Json
$mismatches = [System.Collections.Generic.List[string]]::new()
$checked = 0
function Check-Hash([string]$path, [string]$expected) {
  $script:checked++
  $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $path).Hash.ToLowerInvariant()
  if ($actual -ne $expected) { $script:mismatches.Add($path) }
}
Check-Hash $manifest.generation.oracle.path $manifest.generation.oracle.sha256
foreach ($fixture in $manifest.fixtures) {
  Check-Hash (Join-Path 'contracts/fixtures' $fixture.path) $fixture.rawSha256
  Check-Hash (Join-Path 'contracts/fixtures' $fixture.expectedPath) $fixture.expectedSha256
  foreach ($source in @($fixture.sourceFiles) + @($fixture.testFiles)) {
    Check-Hash (Join-Path 'original-pi' $source.path) $source.sha256
  }
  $raw = (Get-Content -Raw (Join-Path 'contracts/fixtures' $fixture.path) | ConvertFrom-Json).raw
  '{0}: {1}' -f $fixture.domain, (($raw.PSObject.Properties.Name | Sort-Object) -join ',')
}
'PI_REVISION=' + (git -C original-pi rev-parse HEAD)
'HASHES_CHECKED=' + $checked
'HASH_MISMATCHES=' + $mismatches.Count

